using UnityEngine;

namespace Echo.Game.Seasons
{
    /// <summary>
    /// A season's look (seasons doc, "Season themes"): every field is optional and falls back to the normal art.
    /// Looks only: nothing here reaches the simulation, and reskinned hazards keep the original's outline and size
    /// (SeasonArtTests). Generated by Editor/SeasonThemes with the art in Editor/Art/PixelSeasons.
    /// </summary>
    [CreateAssetMenu(menuName = "Echo/Season Theme")]
    public sealed class SeasonTheme : ScriptableObject
    {
        [Tooltip("Matches the schedule's id (SeasonIds).")]
        public string Id = "";
        public string Title = "";

        [Header("Background and palette")]
        [Tooltip("Sky colours by distance, like a palette cosmetic (500 m a stop). Empty keeps the player's palette.")]
        public Color[] PaletteStops = new Color[0];
        [Range(0f, 1f)] public float PaletteBlend = 1f;
        [Tooltip("Replaces the far mountains.")]
        public Sprite FarLayer;
        [Tooltip("Replaces the Graveyard hills.")]
        public Sprite NearLayer;

        [Header("Colours (a user revision: distinct hues, not shades of the sky; alpha 0 keeps the derived colour)")]
        [Tooltip("The far layer's colour.")]
        public Color FarTint = Color.clear;
        [Tooltip("The near layer's colour.")]
        public Color NearTint = Color.clear;
        [Tooltip("The floor, so gaps stand out.")]
        public Color FloorColour = Color.clear;
        [Tooltip("Spikes and blocks, so they read as hazards.")]
        public Color HazardColour = Color.clear;

        [Header("Background effects layer (behind the floor and everything on it)")]
        public SeasonEffect Effect;
        public Sprite[] EffectSprites = new Sprite[0];
        [Tooltip("Each sprite drawn in turn in these colours; empty draws them as they are.")]
        public Color[] EffectColours = new Color[0];
        [Range(0, Views.SeasonEffectsView.MaxParticles)] public int EffectCount = 40;
        [Tooltip("Units a second: down for Falling, sideways for Drifting (negative drifts left).")]
        public float EffectFall = 1.2f;
        [Tooltip("Units either side.")]
        public float EffectSway = 0.3f;
        [Tooltip("Drifting: the share of the view's height, from the bottom, the sprites keep to.")]
        [Range(0.05f, 1f)] public float EffectBand = 1f;
        [Tooltip("How far the layer drifts back as the camera moves (0 fixed to the screen, 1 fixed to the world).")]
        [Range(0f, 1f)] public float EffectParallax = 0.3f;

        [Header("Fireworks (also behind the floor): bursts high in the sky")]
        public bool Fireworks;
        public Sprite FireworkSpark;
        public Color[] FireworkColours = new Color[0];
        [Tooltip("Bursts a minute normally.")]
        public float FireworksPerMinute = 6f;
        [Tooltip("Seasons doc (New Year): when the Daily Haunt board resets at 00:00 UTC, a show this long, ten times as busy.")]
        public float ResetShowSeconds;
        [Tooltip("The toast as the show starts, e.g. HAPPY NEW YEAR!")]
        public string ResetShowToast = "";

        [Header("A silhouette crossing the sky now and then (also behind the floor): Santa's sleigh")]
        public Sprite Flyer;
        public Color FlyerColour = Color.black;
        [Tooltip("Seconds between passes.")]
        public float FlyerEvery = 45f;
        [Tooltip("Units a second across the view.")]
        public float FlyerSpeed = 2.4f;

        [Header("Obstacles: same size and outline as the originals, greyscale, tinted as hazards")]
        public Sprite Spike;
        public Sprite Block;
        [Tooltip("The floor's top edge (snow on the ground).")]
        public Sprite GroundTop;

        [Header("Graves")]
        [Tooltip("The world grave, 12 x 16 like the original.")]
        public Sprite Grave;
        [Tooltip("Drawn in its own colours, not tinted like stone.")]
        public bool GraveInColour;
        [Tooltip("The death screen's large headstone, 56 x 60 with the same plain face for the epitaph.")]
        public Sprite Headstone;

        [Header("Ghosts")]
        [Tooltip("Worn by every ghost but the Nemesis, at the top of its head (the sprite's pivot places it).")]
        public Sprite GhostAccessory;
        [Tooltip("Worn by the Nemesis instead of its horns.")]
        public Sprite NemesisAccessory;

        [Header("Everyone wears (April Fools): the runner and every ghost, for looks only; runs still record the real skin")]
        public string ForceCharacter = "";
        [Tooltip("Said once a session as a run starts.")]
        public string RunToast = "";

        [Header("Death screen")]
        public string DeathLine = "";
        [Tooltip("Only when the Nemesis ended the run.")]
        public bool DeathLineNemesisOnly;

        [Header("Music")]
        [Tooltip("Played once over the music when the season first shows in a session (optional).")]
        public AudioClip Stinger;
        [Tooltip("A user revision: the season's own music, six stems like the main tune's; empty keeps the main tune.")]
        public AudioClip[] MusicStems = new AudioClip[0];

        [Header("Time Run")]
        [Tooltip("A world that travels through eras by distance (World Time Run doc): one theme per era, in order (TimeEras).")]
        public SeasonTheme[] Eras = new SeasonTheme[0];
        [Tooltip("An era's label, shown in the corner as a run reaches it (\"65,000,000 BC\").")]
        public string EraLabel = "";
        [Tooltip("An era's gap: a tile drawn down the pit, in its own colours (lava, a moat, a void).")]
        public Sprite Gap;
        [Tooltip("An era's bounty coin, in its own colours (amber, a data chip); null keeps the gold coin.")]
        public Sprite Coin;
        [Tooltip("An era's ghosts: their colour (bone-white fossils, cyan holograms); clear keeps ghost cyan.")]
        public Color GhostTint = Color.clear;
        [Tooltip("An era's Nemesis colour, always a red; clear keeps the ghost colour.")]
        public Color NemesisTint = Color.clear;
        [Tooltip("An era's ghosts glow faintly, like a phone screen (Today).")]
        public bool GhostGlow;
        [Tooltip("An era's ghosts flicker and glitch like holograms, the Nemesis's horns too (the Far Future).")]
        public bool GhostHologram;
        [Tooltip("Extra parallax layers in their own colours (Today's skyline and window light, the Far Future's sky and moons).")]
        public ExtraLayer[] ExtraLayers = new ExtraLayer[0];
        [Tooltip("An era's floor: a tile in its own colours down the floor (the Far Future's neon grid); null keeps the bricks.")]
        public Sprite Floor;
        [Tooltip("The Far Future breaks out of pixel art: full resolution, 2D lights, bloom, and glow and trails on the pixel sprites.")]
        public bool HighDefinition;
        [Tooltip("Dino Land's 8-bit look: its backdrop and floor rendered at half the internal resolution (LowResView).")]
        public bool HalfResolution;
        [Tooltip("An era's floor edge in its own colours (Dino Land's grass); null keeps the stone edge.")]
        public Sprite FloorTop;
        [Tooltip("An era's hanging ceiling in its own colours (Dino Land's rock overhang); null keeps the bricks.")]
        public Sprite Ceiling;
        [Tooltip("Art pass phase 3: frames turning in each gap of the era (Medieval's waterwheel), below the floor.")]
        public Sprite[] GapWheel = new Sprite[0];
        public float GapWheelFps = 8f;
        [Tooltip("The flyer's second frame, swapped in to beat its wings (Medieval's dragon); null glides.")]
        public Sprite FlyerFlap;
        [Tooltip("Art pass phase 4: the teeth under an era's hanging ceilings (Today's anti-climb spikes); null uses its spike upside down.")]
        public Sprite Teeth;
        [Tooltip("Dusk falling across the era (Today): between these distances in metres the scenery dims towards DuskShade; equal: none.")]
        public float DuskFrom, DuskTo;
        public Color DuskShade = Color.white;
    }
}
